@Component("loanApplication-handler")
@ProcessingGroup("loanApplication-processing-group")
public class LoanApplicationEventHandler {
	
	// core constructor
	LoanApplicationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLoanApplicationEvent
     */
    @EventHandler
    public void handle( CreateLoanApplicationEvent event) {
        entityManager.persist(new LoanApplication(event.getLoanApplicationId(), event.getApplicationNumber(), event.getAmountRequested(), event.getTermMonths(), event.getSubmittedAt(), event.getCustomer(), event.getRiskAssessment(), event.getLoan(), event.getProduct(), event.getPurpose(), event.getStatus()));
    }

    /*
     * @param	event UpdateLoanApplicationEvent
     */
    @EventHandler
    public LoanApplication handle( UpdateLoanApplicationEvent event) {
    	entityManager.merge(new LoanApplication(event.getLoanApplicationId(), event.getApplicationNumber(), event.getAmountRequested(), event.getTermMonths(), event.getSubmittedAt(), event.getCustomer(), event.getRiskAssessment(), event.getLoan(), event.getProduct(), event.getPurpose(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteLoanApplicationEvent
     */
    @EventHandler
    public void on( DeleteLoanApplicationEvent event) {
    	LoanApplication entity = new LoanApplication();
   
    	// ------------------------------------------
    	// apply the LoanApplicationId
    	// ------------------------------------------
    	entity.setLoanApplicationId( event.getLoanApplicationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LoanApplicationRepository loanApplicationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LoanApplicationEventHandler.class.getName());

}
